import json
pool = [[0] * 8 + [None]]
def walk(code, make):
    u = 0
    for k in range(3):
        dg = (code // 8 ** (2 - k)) % 8
        if pool[u][dg] == 0:
            if not make:
                return None
            pool.append([0] * 8 + [None])
            pool[u][dg] = len(pool) - 1
        u = pool[u][dg]
    return u
for code, item in [(5, 21), (13, 8), (200, 3)]:
    pool[walk(code, True)][8] = item
bw = 0
for b in [1, 1, 0]:
    bw = 2 * bw + b
bw = bw // 2
print(json.dumps({"nodes_used": len(pool), "read_13": pool[walk(13, False)][8], "bit_word": bw}))
